def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def dump(val, left, right, root):
    out = []
    queue = [root]
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        if u == -1:
            out.append(-1)
            continue
        out.append(val[u])
        queue.append(left[u])
        queue.append(right[u])
    while out and out[-1] == -1:
        out.pop()
    return out


def deleteFromBst(tree, key):
    if not tree:
        return []
    val, left, right = parse(tree)
    root = 0
    par = -1
    kids = None
    u = root
    while u != -1 and val[u] != key:
        par = u
        kids = left if key < val[u] else right
        u = kids[u]
    if u == -1:
        return list(tree)
    if left[u] == -1 or right[u] == -1:
        child = left[u] if left[u] != -1 else right[u]
        if par == -1:
            root = child
        else:
            kids[par] = child
    else:
        sp = u
        s = right[u]
        while left[s] != -1:
            sp = s
            s = left[s]
        val[u] = val[s]
        if sp == u:
            right[u] = right[s]
        else:
            left[sp] = right[s]
    return dump(val, left, right, root)
